function AccountActions({ dispatch, AccountActions, loanBalance, balance }) {
  return (
    <div>
      <h3>Account Informations</h3>
      <div>
        <div>
          <h4>Account Actions</h4>
          {AccountActions.map((action, index) => (
            <div key={index}>
              <p>{action}</p>
            </div>
          ))}
        </div>
        <div>
          <button className="btn open-btn">Open Account</button>
          <button
            disabled={loanBalance !== 0 || balance !== 0}
            className="btn close-btn"
            onClick={() => dispatch("openAccount")}
          >
            Close Account
          </button>
        </div>
      </div>
    </div>
  );
}

export default AccountActions;
